import { fileURLToPath } from 'node:url'
import { defineConfig } from 'vite-plus'

// vitest 的 projects 模式不继承根配置的 alias：测试阶段直接解析到源码，不需要先 build。
const repoRoot = fileURLToPath(new URL('../..', import.meta.url))
const packageAliases = [
  { find: /^@modelbay\/core\/([\w-]+)$/, replacement: `${repoRoot}packages/core/src/$1.ts` },
  { find: /^@modelbay\/([\w-]+)$/, replacement: `${repoRoot}packages/$1/src/index.ts` },
  { find: /^modelbay$/, replacement: `${repoRoot}packages/modelbay/src/index.ts` },
]

export default defineConfig({
  pack: {
    // `src/models/**/*.ts` is generated by the declarations task; glob keeps the
    // unbundled ESM layout (dist/models/index.mjs) without listing each file.
    // `src/models/index.ts` is also listed explicitly: export-declarations.mjs
    // rmSync's the whole dir before rewriting, so if it is ever run concurrently
    // with pack this makes the build FAIL LOUDLY instead of silently emitting an
    // empty model list. Always run the export script to completion BEFORE pack.
    entry: ['src/index.ts', 'src/node/index.ts', 'src/models/index.ts', 'src/models/**/*.ts'],
    outDir: 'dist',
    format: 'esm',
    dts: { tsconfig: 'tsconfig.build.json' },
    unbundle: true,
    clean: true,
  },
  // 本地测试始终对齐 core 源码，避免 core 的 dist 尚未重建时缺导出；
  // 只作用于 test，vp pack 不受影响，产出仍引用已发布的 @modelbay/core。
  test: { alias: packageAliases },
})
